package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.net.*;
import java.net.http.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real signed four-proof transfer, actual SQLite transactions/races and signed loopback HTTP. */
class OwnerTransferTest {
 @TempDir Path home;CriticalApprovalTest f;CriticalApprovalTest.Person target;Capability owner,second;OwnerTransfer transfer;
 @BeforeEach void setup()throws Exception{f=new CriticalApprovalTest();f.home=home;f.setup();target=f.register();owner=f.admin(f.owner);second=f.admin(f.second);step(target);}
 @AfterEach void close()throws Exception{f.close();}
 void step(CriticalApprovalTest.Person p){var c=f.store.stepUpChallenge(p.account(),p.deviceId(),p.generation());byte[] b=IdentityProtocol.stepUp(f.store.audience(),p.account(),p.deviceId(),c.challenge(),c.expiresAt());f.store.stepUp(p.account(),p.deviceId(),p.generation(),c.challenge(),IdentityProtocol.sign(p.root().getPrivate(),b),IdentityProtocol.sign(p.device().getPrivate(),b));}
 Capability account(CriticalApprovalTest.Person p){String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.capabilityRequest(f.store.audience(),p.account(),p.deviceId(),p.generation(),App.AEGIS,CriticalApprovalTest.key(p.app()),EnumSet.of(Scope.ACCOUNT_READ),600000,f.clock.millis(),n);return f.store.issueCapability(p.account(),p.deviceId(),p.generation(),App.AEGIS,CriticalApprovalTest.key(p.app()),EnumSet.of(Scope.ACCOUNT_READ),600000,f.clock.millis(),n,IdentityProtocol.sign(p.device().getPrivate(),b),IdentityProtocol.sign(p.app().getPrivate(),b));}
 Map<String,Object> challengeData(String id){String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.ownerTransferProposal(f.store.audience(),f.owner.account(),id,f.clock.millis(),n);return Map.of("capability",IdentityProtocol.encodeCapability(owner),"targetAccountId",id,"time",f.clock.millis(),"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(f.owner.app().getPrivate(),IdentityProtocol.requestDigest(owner,"admin.execute",IdentityProtocol.digest(b),f.clock.millis(),n))));}
 OwnerTransfer challenge(){Map<String,Object> d=challengeData(target.account());Map<String,Object> c=f.store.ownerTransferChallenge(owner,target.account(),(Long)d.get("time"),(String)d.get("nonce"),IdentityProtocol.unb64((String)d.get("proof"),64));return transfer=IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.unb64((String)c.get("transfer"),2048));}
 byte[][] proofs(OwnerTransfer t){byte[] a=IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.OWNER_APPROVE),b=IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.SUCCESSOR_ACCEPT);return new byte[][]{IdentityProtocol.sign(f.owner.root().getPrivate(),a),IdentityProtocol.sign(f.owner.device().getPrivate(),a),IdentityProtocol.sign(target.root().getPrivate(),b),IdentityProtocol.sign(target.device().getPrivate(),b)};}
 Map<String,Object> permit(OwnerTransfer t,boolean approved){byte[] body=IdentityProtocol.ownerTransferBytes(t);Map<String,Object> p=f.request(f.owner,owner,"owner.transfer",body);if(approved)f.approve(f.second,second,p,body);return p;}
 Map<String,Object> completion(OwnerTransfer t,Map<String,Object> permit,byte[][] proofs){String n=IdentityProtocol.nonce();byte[] critical=IdentityProtocol.criticalApproval(f.store.audience(),f.owner.account(),"owner.transfer",(String)permit.get("requestId"),IdentityProtocol.ownerTransferBytes(t),(Long)permit.get("expiresAt"));Map<String,Object> d=new LinkedHashMap<>();d.put("capability",IdentityProtocol.encodeCapability(owner));d.put("challenge",t.challenge);d.put("requestId",permit.get("requestId"));d.put("ownerRootProof",IdentityProtocol.b64(proofs[0]));d.put("ownerDeviceProof",IdentityProtocol.b64(proofs[1]));d.put("targetRootProof",IdentityProtocol.b64(proofs[2]));d.put("targetDeviceProof",IdentityProtocol.b64(proofs[3]));d.put("time",f.clock.millis());d.put("nonce",n);d.put("proof",IdentityProtocol.b64(IdentityProtocol.sign(f.owner.app().getPrivate(),IdentityProtocol.requestDigest(owner,"admin.execute",IdentityProtocol.digest(critical),f.clock.millis(),n))));return d;}
 void complete(IdentityStore store,Map<String,Object> d){store.completeOwnerTransfer(owner,(String)d.get("challenge"),(String)d.get("requestId"),IdentityProtocol.unb64((String)d.get("ownerRootProof"),64),IdentityProtocol.unb64((String)d.get("ownerDeviceProof"),64),IdentityProtocol.unb64((String)d.get("targetRootProof"),64),IdentityProtocol.unb64((String)d.get("targetDeviceProof"),64),(Long)d.get("time"),(String)d.get("nonce"),IdentityProtocol.unb64((String)d.get("proof"),64));}
 void complete(OwnerTransfer t,Map<String,Object> p){complete(f.store,completion(t,p,proofs(t)));}
 void unchanged(){assertEquals(true,f.store.profile(f.owner.account()).get("ownerBadge"));assertEquals(false,f.store.profile(target.account()).get("ownerBadge"));assertTrue(f.store.verifyAudit());}
 @Test void fourProofsAndIndependentPermitAtomicallySwitchOwnerAndRevokeBothSessions(){Capability oldTarget=account(target);OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);byte[] oldRoot=CriticalApprovalTest.key(f.owner.root()),newRoot=CriticalApprovalTest.key(target.root());f.delegated.add(f.owner.account());complete(t,p);assertFalse(f.store.isActive(owner));assertFalse(f.store.isActive(oldTarget));assertEquals(false,f.store.currentAuthority(f.owner.account()).get("authorityAdministrator"));assertEquals(true,f.store.profile(target.account()).get("ownerBadge"));assertEquals(false,f.store.profile(f.owner.account()).get("delegatedAdministrator"));assertEquals(IdentityProtocol.b64(oldRoot),f.store.publicProfile(f.owner.account()).get("accountPublicKey"));assertEquals(IdentityProtocol.b64(newRoot),f.store.publicProfile(target.account()).get("accountPublicKey"));assertThrows(IdentityException.class,()->complete(t,p));assertTrue(f.store.verifyAudit());}
 @Test void pendingPermitCannotCompleteButFailedAttemptDoesNotSpendIt(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,false);assertThrows(IdentityException.class,()->complete(t,p));unchanged();f.approve(f.second,second,p,IdentityProtocol.ownerTransferBytes(t));complete(t,p);assertEquals(true,f.store.profile(target.account()).get("ownerBadge"));}
 @Test void eachWrongKeyIsRejectedWithoutConsumingValidPermit()throws Exception{OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);for(int i=0;i<4;i++){byte[][] signatures=proofs(t);signatures[i]=IdentityProtocol.sign(CriticalApprovalTest.pair().getPrivate(),new byte[]{1});assertThrows(IdentityException.class,()->complete(f.store,completion(t,p,signatures)));unchanged();}complete(t,p);}
 @Test void oppositeConsentRoleAndChangedCanonicalFieldsCannotBeReused(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);byte[][] wrong=proofs(t);wrong[0]=IdentityProtocol.sign(f.owner.root().getPrivate(),IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.SUCCESSOR_ACCEPT));assertThrows(IdentityException.class,()->complete(f.store,completion(t,p,wrong)));OwnerTransfer altered=new OwnerTransfer(t.audience,t.challenge,t.ownerAccountId,t.ownerDeviceId,t.ownerGeneration,t.targetAccountId,t.targetDeviceId,t.targetGeneration,t.authorityEpoch+1,t.expiresAt);assertThrows(IdentityException.class,()->complete(f.store,completion(t,p,proofs(altered))));unchanged();}
 @Test void exactExpiryAndMissingFreshTargetStepUpFailClosed(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);f.clock.value+=120000;assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void unsteppedTargetCannotAcceptEvenWithValidRootAndDeviceProofs()throws Exception{target=f.register();OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void targetGenerationChangeRejectsPendingTransfer(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);String n=IdentityProtocol.nonce();f.store.login(target.account(),target.deviceId(),f.clock.millis(),n,IdentityProtocol.sign(target.device().getPrivate(),IdentityProtocol.login(f.store.audience(),target.account(),target.deviceId(),f.clock.millis(),n)));assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void ownerGenerationChangeRejectsPendingTransfer(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);String n=IdentityProtocol.nonce();f.store.login(f.owner.account(),f.owner.deviceId(),f.clock.millis(),n,IdentityProtocol.sign(f.owner.device().getPrivate(),IdentityProtocol.login(f.store.audience(),f.owner.account(),f.owner.deviceId(),f.clock.millis(),n)));assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void revokedIndependentApproverInvalidatesAlreadyApprovedPermit(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);f.delegated.remove(f.second.account());assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void roleEpochChangeInvalidatesExactPendingConsent(){OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);String n=IdentityProtocol.nonce();byte[] proposal=IdentityProtocol.firstDelegateProposal(f.store.audience(),f.owner.account(),f.second.account(),"Администратор",f.clock.millis(),n);Map<String,Object> d=f.store.firstDelegateChallenge(owner,f.second.account(),"Администратор",f.clock.millis(),n,IdentityProtocol.sign(f.owner.app().getPrivate(),IdentityProtocol.requestDigest(owner,"admin.execute",IdentityProtocol.digest(proposal),f.clock.millis(),n)));byte[] b=IdentityProtocol.unb64((String)d.get("proofBytes"),2048);f.store.completeFirstDelegation((String)d.get("challenge"),IdentityProtocol.sign(f.owner.root().getPrivate(),b),IdentityProtocol.sign(f.owner.device().getPrivate(),b),IdentityProtocol.sign(f.second.root().getPrivate(),b),IdentityProtocol.sign(f.second.device().getPrivate(),b));assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void boundedPendingChallengeSelfUnknownAndDuplicateFailClosed(){assertThrows(IllegalArgumentException.class,()->challengeData(f.owner.account()));Map<String,Object> unknown=challengeData("0".repeat(64));assertThrows(IdentityException.class,()->f.store.ownerTransferChallenge(owner,"0".repeat(64),(Long)unknown.get("time"),(String)unknown.get("nonce"),IdentityProtocol.unb64((String)unknown.get("proof"),64)));challenge();for(int i=0;i<40;i++)assertThrows(IdentityException.class,this::challenge);unchanged();}
 @Test void twoSqlConnectionsCannotConsumeTransferTwice()throws Exception{OwnerTransfer t=challenge();Map<String,Object> d=completion(t,permit(t,true),proofs(t));try(IdentityStore other=new IdentityStore(home.resolve("identity.db"),f.service,f.audit,f.clock,f.delegated::contains)){ExecutorService workers=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{java.util.function.Function<IdentityStore,Boolean> run=store->{try{complete(store,d);return true;}catch(IdentityException deny){return false;}};Future<Boolean>a=workers.submit(()->{start.await();return run.apply(f.store);}),b=workers.submit(()->{start.await();return run.apply(other);});start.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));assertEquals(true,f.store.profile(target.account()).get("ownerBadge"));assertTrue(f.store.verifyAudit());}finally{workers.shutdownNow();}}}
 @Test void actualSignedHttpInspectCompletionAndReplay()throws Exception{try(IdentityHttpServer http=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),f.store,f.service)){http.start();Map<String,Object> created=rpc(http,"ownerTransferChallenge",challengeData(target.account()));OwnerTransfer t=IdentityProtocol.decodeOwnerTransfer(IdentityProtocol.unb64((String)created.get("transfer"),2048));Capability cap=account(target);String n=IdentityProtocol.nonce();byte[] bytes=IdentityProtocol.ownerTransferInspection(f.store.audience(),t.challenge,f.clock.millis(),n);Map<String,Object> inspect=Map.of("capability",IdentityProtocol.encodeCapability(cap),"challenge",t.challenge,"time",f.clock.millis(),"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(target.app().getPrivate(),IdentityProtocol.requestDigest(cap,"account.read",IdentityProtocol.digest(bytes),f.clock.millis(),n))));assertEquals(created,rpc(http,"ownerTransferInspect",inspect));assertThrows(IdentityException.class,()->rpc(http,"ownerTransferInspect",inspect));Map<String,Object> completion=completion(t,permit(t,true),proofs(t));assertEquals(Map.of("transferred",true,"sessionsRevoked",true),rpc(http,"ownerTransferComplete",completion));assertThrows(IdentityException.class,()->rpc(http,"ownerTransferComplete",completion));assertEquals(true,f.store.profile(target.account()).get("ownerBadge"));}}
 @Test void exactCodecDomainsAndTrailingBytesCannotBeConfused(){OwnerTransfer t=challenge();byte[] bytes=IdentityProtocol.ownerTransferBytes(t);assertArrayEquals(bytes,IdentityProtocol.ownerTransferBytes(IdentityProtocol.decodeOwnerTransfer(bytes)));assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeOwnerTransfer(Arrays.copyOf(bytes,bytes.length+1)));assertFalse(Arrays.equals(IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.OWNER_APPROVE),IdentityProtocol.ownerTransferConsent(t,OwnerTransferRole.SUCCESSOR_ACCEPT)));assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeFirstDelegation(bytes));}
 @Test void targetStepUpCanExpireBeforeStillLiveTransferChallenge(){f.clock.value+=119001;owner=f.admin(f.owner);second=f.admin(f.second);OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);f.clock.value+=1000;assertTrue(f.clock.millis()<t.expiresAt);assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 @Test void ownerRecoveryNeedsTwoOtherAdminsBeforeAdministrativeUse()throws Exception{KeyPair next=CriticalApprovalTest.pair();String n=IdentityProtocol.nonce();var c=f.store.challengeDevice(f.owner.account(),CriticalApprovalTest.key(next),f.clock.millis(),n,IdentityProtocol.sign(next.getPrivate(),IdentityProtocol.login(f.store.audience(),f.owner.account(),IdentityProtocol.id(CriticalApprovalTest.key(next)),f.clock.millis(),n)));byte[] body=IdentityProtocol.recovery(f.store.audience(),f.owner.account(),c.challenge(),CriticalApprovalTest.key(next),c.expiresAt());f.store.recoverDevice(f.owner.account(),c.challenge(),IdentityProtocol.sign(f.owner.root().getPrivate(),body),IdentityProtocol.sign(f.owner.recovery().getPrivate(),body));assertFalse(f.store.isActive(owner));assertEquals(true,f.store.profile(f.owner.account()).get("sensitiveRecoveryPending"));CriticalApprovalTest.Person reviewer=f.register();f.delegated.add(reviewer.account());Capability reviewerCap=f.admin(reviewer);byte[] review=IdentityProtocol.accountRecoveryApproval(f.owner.account());Map<String,Object> permit=f.request(f.second,second,"account.sensitive_recovery.approve",review);f.approve(reviewer,reviewerCap,permit,review);String nonce=IdentityProtocol.nonce();byte[] exact=IdentityProtocol.criticalApproval(f.store.audience(),f.second.account(),"account.sensitive_recovery.approve",(String)permit.get("requestId"),review,(Long)permit.get("expiresAt"));f.store.approveSensitiveRecovery(second,(String)permit.get("requestId"),f.owner.account(),f.clock.millis(),nonce,IdentityProtocol.sign(f.second.app().getPrivate(),IdentityProtocol.requestDigest(second,"admin.execute",IdentityProtocol.digest(exact),f.clock.millis(),nonce)));assertEquals(false,f.store.profile(f.owner.account()).get("sensitiveRecoveryPending"));assertEquals(true,f.store.profile(f.owner.account()).get("ownerBadge"));assertTrue(f.store.verifyAudit());}
 @Test void actualHttpFirstDelegationInspectionIsParticipantBoundAndOneUse()throws Exception{try(IdentityHttpServer http=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),f.store,f.service)){http.start();String n=IdentityProtocol.nonce();byte[] proposal=IdentityProtocol.firstDelegateProposal(f.store.audience(),f.owner.account(),target.account(),"Смотритель",f.clock.millis(),n);Map<String,Object> created=rpc(http,"firstDelegateChallenge",Map.of("capability",IdentityProtocol.encodeCapability(owner),"targetAccountId",target.account(),"roleName","Смотритель","time",f.clock.millis(),"nonce",n,"proof",IdentityProtocol.b64(IdentityProtocol.sign(f.owner.app().getPrivate(),IdentityProtocol.requestDigest(owner,"admin.execute",IdentityProtocol.digest(proposal),f.clock.millis(),n)))));FirstDelegation delegation=IdentityProtocol.decodeFirstDelegation(IdentityProtocol.unb64((String)created.get("proofBytes"),2048));Capability cap=account(target);String inspectNonce=IdentityProtocol.nonce();byte[] query=IdentityProtocol.firstDelegationInspection(f.store.audience(),delegation.challenge,f.clock.millis(),inspectNonce);Map<String,Object> data=Map.of("capability",IdentityProtocol.encodeCapability(cap),"challenge",delegation.challenge,"time",f.clock.millis(),"nonce",inspectNonce,"proof",IdentityProtocol.b64(IdentityProtocol.sign(target.app().getPrivate(),IdentityProtocol.requestDigest(cap,"account.read",IdentityProtocol.digest(query),f.clock.millis(),inspectNonce))));Map<String,Object> inspected=rpc(http,"firstDelegateInspect",data);assertArrayEquals(IdentityProtocol.firstDelegationBytes(delegation),IdentityProtocol.unb64((String)inspected.get("delegation"),2048));assertThrows(IdentityException.class,()->rpc(http,"firstDelegateInspect",data));byte[] consent=IdentityProtocol.firstDelegationBytes(delegation);assertEquals(Map.of("delegated",true),rpc(http,"firstDelegateComplete",Map.of("challenge",delegation.challenge,"ownerRootProof",IdentityProtocol.b64(IdentityProtocol.sign(f.owner.root().getPrivate(),consent)),"ownerDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(f.owner.device().getPrivate(),consent)),"targetRootProof",IdentityProtocol.b64(IdentityProtocol.sign(target.root().getPrivate(),consent)),"targetDeviceProof",IdentityProtocol.b64(IdentityProtocol.sign(target.device().getPrivate(),consent)))));assertEquals(true,f.store.profile(target.account()).get("delegatedAdministrator"));}}
 @Test void successorCannotAlsoApproveTheAdministrativePermit(){target=f.second;OwnerTransfer t=challenge();Map<String,Object> p=permit(t,true);assertThrows(IdentityException.class,()->complete(t,p));unchanged();}
 Map<String,Object> rpc(IdentityHttpServer server,String operation,Map<String,Object> data)throws Exception{String nonce=IdentityProtocol.nonce();byte[] request=IdentityJson.bytes(Map.of("operation",operation,"nonce",nonce,"data",data));HttpResponse<byte[]> response=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+server.port()+"/identity/v1")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(request)).timeout(java.time.Duration.ofSeconds(3)).build(),HttpResponse.BodyHandlers.ofByteArray());assertTrue(IdentityProtocol.verify(CriticalApprovalTest.key(f.service),IdentityProtocol.response(f.store.audience(),nonce,request,response.body()),IdentityProtocol.unb64(response.headers().firstValue("AEGIS-Signature").orElseThrow(),64)));Map<String,Object> document=IdentityJson.parse(response.body());if(!Boolean.TRUE.equals(document.get("ok")))throw new IdentityException((String)((Map<?,?>)document.get("error")).get("code"));@SuppressWarnings("unchecked")Map<String,Object> result=(Map<String,Object>)document.get("data");return result;}
}
